
DROP TABLE IF EXISTS bathymetry_contours;
CREATE TABLE bathymetry_contours (
  id SERIAL PRIMARY KEY,
  depth_m DOUBLE PRECISION NOT NULL,
  depth_band TEXT NOT NULL,
  geom geometry(LineString, 4326) NOT NULL
);

CREATE INDEX bathymetry_contours_geom_idx ON bathymetry_contours USING GIST (geom);
SELECT depth_m, count(*) FROM bathymetry_contours GROUP BY depth_m ORDER BY depth_m;